Part.Source:
styles WorkWithPlusDS
{
	@import WWPBaseObjects.WorkWithPlusBaseDS;

    DIV.gx-mask
    {
        background-color: black;
        background-image: gx-image(LoadingGif);
        background-repeat: no-repeat;
        left: 0px;
        position: absolute;
        top: 0px;
        height: 100%;
        width: 100%;
        animation:  entermask 1s;
        -webkit-animation:  entermask 1s;
        -ms-filter: "alpha(opacity=10)";
        opacity: .30;
        display: inline-block;
        background-position: center;
        background-size: 64px;
    }
    .MinWidth-25perc
    {
        min-width: 25%;
    }
    .MinWidth-8perc
    {
        min-width: 8%;
    }
    .FixedFreeStyleColumn-100
    {
        width: 100px;
        overflow-wrap: anywhere;
        padding-bottom: 2px;
        padding-left: 5px;
        padding-right: 5px;
        padding-top: 2px;
        white-space: nowrap;
        vertical-align: middle;
    }
    .FixedFreeStyleCell-65
    {
        @include FixedFreeStyleColumn-100;
        width: 65px;
        padding-left: 2px;
        padding-right: 2px;
    }
    .FixedFreeStyleCell-35
    {
        @include FixedFreeStyleColumn-100;
        width: 35px;
        padding-left: 1px;
        padding-right: 1px;
    }
    .RightTextDataDescription
    {
        // @include DataDescription;
        white-space: normal;
        font-size: $fontSizes.s;
        font-weight: normal;
        display: block;
        padding-left: 20px;
        color: $colors.gray07;
    }
}
